module.exports = function(RED) {
    "use strict";
    var vm = require("vm");

    // TypeScript compiler integration
    let typescript;
    try {
        typescript = require('typescript');
    } catch(err) {
        RED.log.warn("TypeScript not available. Install 'typescript' package for TypeScript support.");
    }

    // Zod integration for schema validation
    let zod;
    try {
        zod = require('zod');
    } catch(err) {
        RED.log.warn("Zod not available. Install 'zod' package for schema validation support.");
    }

    function SchemaNode(n) {
        RED.nodes.createNode(this, n);
        var node = this;
        this.name = n.name;
        this.schemaCode = n.schemaCode;
        this.schemaName = n.schemaName || 'Schema';
        this.export = n.export || false; // Whether to export this schema globally

        var compiledSchema = null;

        // Compile the schema on startup
        if (this.schemaCode && typescript && zod) {
            try {
                var compilationResult = this.compileSchema(this.schemaCode);
                if (compilationResult.success) {
                    compiledSchema = compilationResult.schema;
                    
                    // Export schema globally if requested
                    if (this.export && this.schemaName) {
                        this.exportSchemaGlobally(this.schemaName, compiledSchema);
                    }
                } else {
                    this.error("Schema compilation failed: " + compilationResult.error);
                    return;
                }
            } catch(err) {
                this.error("Schema compilation error: " + err.message);
                return;
            }
        }

        this.on("input", function(msg, send, done) {
            if (!compiledSchema) {
                node.error("No compiled schema available", msg);
                done();
                return;
            }

            try {
                // Validate the message payload against the schema
                var validatedData = compiledSchema.parse(msg.payload);
                
                // Replace payload with validated/transformed data
                msg.payload = validatedData;
                
                // Add validation metadata
                msg._validation = {
                    schema: node.schemaName,
                    validated: true,
                    timestamp: new Date().toISOString()
                };

                send(msg);
                done();
            } catch(validationError) {
                // Handle validation errors
                if (validationError.name === 'ZodError') {
                    var errorDetails = validationError.errors.map(err => ({
                        path: err.path.join('.'),
                        message: err.message,
                        code: err.code
                    }));
                    
                    msg._validation = {
                        schema: node.schemaName,
                        validated: false,
                        errors: errorDetails,
                        timestamp: new Date().toISOString()
                    };
                    
                    node.error("Schema validation failed: " + JSON.stringify(errorDetails), msg);
                } else {
                    node.error("Validation error: " + validationError.message, msg);
                }
                done();
            }
        });

        this.on("close", function() {
            // Clean up any global exports
            if (this.export && this.schemaName) {
                this.removeGlobalSchema(this.schemaName);
            }
        });
    }

    // Compile TypeScript schema code
    SchemaNode.prototype.compileSchema = function(schemaCode) {
        if (!typescript || !zod) {
            return { success: false, error: "TypeScript or Zod not available" };
        }

        try {
            // Add necessary imports and wrapper
            var wrappedCode = `
                const { z } = require('zod');
                ${schemaCode}
                
                // Export the schema (assume last assignment or export)
                if (typeof module !== 'undefined' && module.exports) {
                    // Node.js environment
                } else {
                    // Return the schema for evaluation
                    return schema;
                }
            `;

            // Compile TypeScript to JavaScript
            var compilerOptions = {
                target: typescript.ScriptTarget.ES2020,
                module: typescript.ModuleKind.CommonJS,
                strict: false,
                esModuleInterop: true,
                skipLibCheck: true
            };

            var compiledJS = typescript.transpile(wrappedCode, compilerOptions);

            // Create a sandbox to execute the schema code
            var sandbox = {
                require: require,
                module: { exports: {} },
                exports: {},
                z: zod,
                zod: zod,
                console: console
            };

            var context = vm.createContext(sandbox);
            var script = vm.createScript(compiledJS);
            var result = script.runInContext(context);

            // Extract the schema from module.exports or return value
            var schema = result || sandbox.module.exports || sandbox.exports;
            
            if (!schema || typeof schema.parse !== 'function') {
                return { success: false, error: "No valid Zod schema found in code" };
            }

            return { success: true, schema: schema };
        } catch (error) {
            return { success: false, error: error.message };
        }
    };

    // Export schema to global context for use in other nodes
    SchemaNode.prototype.exportSchemaGlobally = function(name, schema) {
        var globalContext = this.context().global;
        var schemas = globalContext.get('__nodeRedSchemas') || {};
        schemas[name] = schema;
        globalContext.set('__nodeRedSchemas', schemas);
        
        this.log("Schema '" + name + "' exported globally");
    };

    // Remove schema from global context
    SchemaNode.prototype.removeGlobalSchema = function(name) {
        var globalContext = this.context().global;
        var schemas = globalContext.get('__nodeRedSchemas') || {};
        delete schemas[name];
        globalContext.set('__nodeRedSchemas', schemas);
        
        this.log("Schema '" + name + "' removed from global context");
    };

    RED.nodes.registerType("schema", SchemaNode);
};